'use client';
import { useCallback, useEffect, useRef, useState } from 'react';
import SplitLineReveal from '../../../effects/split-line-reveal';
import { meta as splitMeta } from '../../../effects/split-line-reveal/meta';
import { useScrollProgress, useStudioMotion } from '../../../motion';
import { StudioCanvas, defaultQualityProfiles, describeModelError, detectCapabilities, resolveModelUrl, resolveModelVariant, useModelManifest, type QualityLevel } from '../../../three';
import type { EffectMeta, ParamValues } from '../../../types';
import { Director } from './Director';
import styles from './styles.module.css';

const MANIFEST_URL = '/models/pulse-speaker.manifest.json';
const POSTER = '/models/pulse-speaker.webp';
const defaults = (m: EffectMeta): ParamValues => Object.fromEntries(m.params.map((p) => [p.key, p.default]));
const BEATS = [
  { id: 'night', label: 'Night' },
  { id: 'sound', label: 'Sound' },
  { id: 'dial', label: 'Dial' },
] as const;

export default function CinematicLanding() {
  const { reduced } = useStudioMotion();
  const scene = useRef<HTMLElement>(null);
  const beatEls = useRef<(HTMLElement | null)[]>([]);
  const progress = useRef(0);
  const invalidateRef = useRef<(() => void) | null>(null);
  const [webgl, setWebgl] = useState<boolean | null>(null);
  const [skip, setSkip] = useState(0);
  const [introDone, setIntroDone] = useState(false);
  const [ambience, setAmbience] = useState(true);
  const [beat, setBeat] = useState(0);
  const [level, setLevel] = useState<QualityLevel | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => { setWebgl(detectCapabilities().webgl); }, []);
  const { manifest } = useModelManifest(MANIFEST_URL);
  const variant = manifest && level ? resolveModelVariant(manifest, defaultQualityProfiles[level].modelVariant) : null;
  const url = variant ? resolveModelUrl(variant.file, MANIFEST_URL) : null;

  useScrollProgress(scene, (p) => {
    progress.current = p;
    invalidateRef.current?.();
    const b = Math.min(BEATS.length - 1, Math.round(p * (BEATS.length - 1)));
    setBeat((prev) => (prev === b ? prev : b));
  }, { mode: 'contain' });

  const onIntroDone = useCallback(() => setIntroDone(true), []);
  const onLoaded = useCallback(() => setLoaded(true), []);
  const live = webgl === true && !error;
  const introRunning = live && !reduced && !introDone;
  const goTo = (i: number) => beatEls.current[i]?.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });

  return (
    <div data-stage="ink" className={`${styles.root} text-ink`}>
      <section ref={scene} className={styles.scene} aria-label="Pulse Night Edition">
        <div className={styles.sticky}>
          <StudioCanvas
            label="The Pulse speaker, night edition, on a dark plinth"
            description="A compact charcoal speaker with an orange dial and trim ring stands on a black plinth under a single hard key light and a cool rim light; a cyan ring around the dial glows softly. Scrolling moves the camera from a three-quarter view to the grille and then down onto the dial."
            frameloop={!reduced && ambience ? 'always' : 'demand'}
            onQualityChange={setLevel}
            onSceneError={setError}
            camera={{ fov: 26, near: 0.1, far: 60, position: [-4.6, 0.3, 3.6] }}
            style={{ position: 'absolute', inset: 0 }}
            fallback={<img src={POSTER} alt="Studio render of the Pulse speaker in graphite and ember" className={styles.poster} />}
          >
            {url ? (
              <Director
                progress={progress} invalidateRef={invalidateRef} skip={skip} playIntro={!reduced} ambience={ambience} reduced={reduced}
                onIntroDone={onIntroDone} onLoaded={onLoaded} onError={setError} variantUrl={url}
              />
            ) : null}
          </StudioCanvas>
          {error ? (
            <div className="absolute inset-0">
              <img src={POSTER} alt="Studio render of the Pulse speaker in graphite and ember" className={styles.poster} />
              <p role="alert" className="absolute bottom-4 right-4 m-0 max-w-[24rem] rounded-[6px] border border-line bg-surface p-3 text-[13px]">{describeModelError(error)} Showing the still render.</p>
            </div>
          ) : null}
          {live && !loaded ? <p className="mk-label absolute bottom-4 right-4 m-0 text-muted" role="status">Loading the speaker…</p> : null}
        </div>

        <div className={styles.beats}>
          <div className={styles.chrome}>
            <div className={styles.chromeRow}>
              <p className="mk-label m-0 text-ink">kiln<span className="text-signal">.</span>audio <span className="text-muted">/ night edition</span></p>
              <div className="flex items-center gap-2">
                {introRunning ? (
                  <button type="button" className={styles.pill} onClick={() => setSkip((n) => n + 1)}>Skip intro</button>
                ) : live && !reduced ? (
                  <button type="button" className={styles.pill} onClick={() => setAmbience((a) => !a)}>{ambience ? 'Pause light' : 'Play light'}</button>
                ) : null}
              </div>
            </div>
            <nav aria-label="Sections" className={styles.nav}>
              {BEATS.map((b, i) => (
                <button key={b.id} type="button" className={styles.navItem} aria-current={beat === i ? 'step' : undefined} onClick={() => goTo(i)}>
                  <span className="font-mono text-[11px]">{String(i + 1).padStart(2, '0')}</span> {b.label}
                </button>
              ))}
            </nav>
          </div>

          <article ref={(el) => { beatEls.current[0] = el; }} className={styles.beat}>
            <div className={styles.copy}>
              <p className="mk-label m-0 text-muted">Pulse · Night Edition · fictional</p>
              <div className={styles.headline}>
                <SplitLineReveal params={{ ...defaults(splitMeta), text: 'Built for the hour after midnight.', stagger: 64, duration: 980, rise: 105, skew: true }} />
              </div>
              <p className="m-0 max-w-[36ch] text-[16px] leading-relaxed text-muted">
                Graphite and ember, with a status ring that breathes while it plays. One dial, no screen, nothing to set up at one in the morning.
              </p>
              <p className="mk-label m-0 mt-2 flex items-center gap-3 text-muted"><span aria-hidden="true" className={styles.rule} />Scroll to look closer</p>
            </div>
          </article>

          <article ref={(el) => { beatEls.current[1] = el; }} className={`${styles.beat} ${styles.beatRight}`}>
            <div className={styles.copy}>
              <p className="m-0 font-mono text-[12px] tracking-[0.08em] text-signal">01 — The sound</p>
              <h3 className={styles.title}>Small room, <span className="font-serif font-normal italic">full voice.</span></h3>
              <p className="m-0 max-w-[36ch] text-[16px] leading-relaxed text-muted">
                A single 52 mm driver behind a perforated grille, tuned for voices and late playlists. It plays quietly without thinning out.
              </p>
            </div>
          </article>

          <article ref={(el) => { beatEls.current[2] = el; }} className={styles.beat}>
            <div className={styles.copy}>
              <p className="m-0 font-mono text-[12px] tracking-[0.08em] text-signal">02 — The dial</p>
              <h3 className={styles.title}>Turn it. <span className="font-serif font-normal italic">That’s all.</span></h3>
              <p className="m-0 max-w-[36ch] text-[16px] leading-relaxed text-muted">
                Turn for volume, press to pause. The ring beneath the dial glows while it is paired — the only light it makes in a dark room.
              </p>
            </div>
          </article>
        </div>
      </section>

      <section className="mx-auto max-w-[1280px] px-4 pb-24 pt-16 @3xl:px-8" aria-labelledby="night-specs">
        <div className="grid gap-8 border-t border-line-strong pt-6 @4xl:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]">
          <h3 id="night-specs" className="m-0 font-serif text-[clamp(2rem,6cqi,3.4rem)] font-normal italic leading-none">The small print.</h3>
          <div>
            <dl className="m-0 grid grid-cols-1 gap-x-8 @xl:grid-cols-2">
              {[['Size', '223 × 144 × 85 mm'], ['Driver', 'One 52 mm full-range'], ['Controls', 'One knurled dial'], ['Light', 'Status ring, paired only'], ['Finish', 'Graphite shell, ember hardware'], ['Price', 'Not for sale — Pulse is fictional']].map(([k, v]) => (
                <div key={k} className="flex items-baseline justify-between gap-4 border-b border-line py-2.5 text-[14px]">
                  <dt className="text-muted">{k}</dt><dd className="m-0 text-right">{v}</dd>
                </div>
              ))}
            </dl>
            <p className="m-0 mt-5 text-[13.5px] leading-relaxed text-muted">
              Want it in another colour? <a href="/demos/3d/product-configurator" className="text-ink underline underline-offset-4">Open the configurator</a>. Without WebGL this page shows the same copy over a still render; with reduced motion the camera skips the opening move and the lights hold still.
            </p>
          </div>
        </div>
      </section>
    </div>
  );
}

'use client';
/**
 * The scene and its camera director. Three phases share one camera:
 *  1. intro    — a choreographed arc on load (Catmull-Rom path, eased), interrupted by Skip or by scrolling;
 *  2. follow   — the camera damps towards the pose for the current scroll progress (beats held, eased between);
 *  3. reduced  — no intro and no easing: the camera cuts to the pose of the beat in view.
 * Lighting "ambience" (a slow key-light sweep and the status ring's breathing glow) runs only when allowed.
 */
import { useFrame, useThree } from '@react-three/fiber';
import { Suspense, useCallback, useEffect, useMemo, useRef, useState, type MutableRefObject } from 'react';
import { CatmullRomCurve3, MathUtils, Vector3, type Mesh, type MeshStandardMaterial, type PerspectiveCamera } from 'three';
import {
  AnimationPlayer, LightingRig, Model, ModelBoundary, PartController, lightingPresets,
  type AnimationPlayerHandle, type LightingRigHandle, type LoadedModel, type PartControllerCore,
} from '../../../three';

type V3 = [number, number, number];
interface Pose { position: V3; target: V3; fov: number }

/** One pose per beat, for landscape and portrait framings (portrait keeps the subject in the upper half). */
export const BEAT_POSES: { wide: Pose; tall: Pose }[] = [
  { wide: { position: [2.9, 1.7, 5.3], target: [-0.75, 0.68, 0], fov: 30 }, tall: { position: [2.6, 2.2, 6.6], target: [0, 0.2, 0], fov: 34 } },
  { wide: { position: [-1.25, 0.95, 3.35], target: [0.5, 0.6, 0.1], fov: 30 }, tall: { position: [-0.9, 1.2, 4.6], target: [0.1, 0.25, 0.1], fov: 34 } },
  { wide: { position: [1.25, 3.1, 1.55], target: [-0.05, 1.12, -0.05], fov: 32 }, tall: { position: [0.95, 3.6, 2.2], target: [0.3, 0.8, 0], fov: 36 } },
];
const INTRO_SECONDS = 5.2;
const INTRO_PATH: V3[] = [[-4.6, 0.3, 3.6], [-2.6, 1.1, 5.8], [0.4, 2.4, 6.4]];
const INTRO_TARGET_FROM: V3 = [0, 0.55, 0];
const KEY = lightingPresets['product-contrast'].key;

const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);
const smooth = (t: number) => t * t * (3 - 2 * t);

export interface DirectorProps {
  /** Scroll progress through the pinned section, 0..1 (written by the page, read every frame). */
  progress: MutableRefObject<number>;
  /** Set by the scene so the page can request a frame (render-on-demand when ambience is off). */
  invalidateRef: MutableRefObject<(() => void) | null>;
  skip: number;
  playIntro: boolean;
  ambience: boolean;
  reduced: boolean;
  onIntroDone: () => void;
  onLoaded: () => void;
  onError: (e: Error) => void;
  variantUrl: string;
}

function damp3(cur: Vector3, goal: Vector3, vel: Vector3, smoothTime: number, dt: number) {
  const omega = 2 / smoothTime, x = omega * dt, k = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  for (const a of ['x', 'y', 'z'] as const) {
    const change = cur[a] - goal[a], temp = (vel[a] + omega * change) * dt;
    vel[a] = (vel[a] - omega * temp) * k;
    cur[a] = goal[a] + (change + temp) * k;
  }
}

export function Director({ progress, invalidateRef, skip, playIntro, ambience, reduced, onIntroDone, onLoaded, onError, variantUrl }: DirectorProps) {
  const camera = useThree((s) => s.camera) as PerspectiveCamera;
  const invalidate = useThree((s) => s.invalidate);
  const lights = useRef<LightingRigHandle>(null);
  const player = useRef<AnimationPlayerHandle>(null);
  const ring = useRef<MeshStandardMaterial | null>(null);
  const curve = useMemo(() => new CatmullRomCurve3(INTRO_PATH.map((p) => new Vector3(...p)), false, 'centripetal'), []);
  const s = useRef({
    phase: (playIntro && !reduced ? 'intro' : 'follow') as 'intro' | 'follow',
    t: 0, time: 0, pos: new Vector3(), tgt: new Vector3(), vPos: new Vector3(), vTgt: new Vector3(),
    goalPos: new Vector3(), goalTgt: new Vector3(), fov: 30, placed: false,
  });
  const live = useRef({ reduced, ambience, onIntroDone });
  live.current = { reduced, ambience, onIntroDone };
  invalidateRef.current = invalidate;

  const onModel = useCallback(() => { onLoaded(); invalidate(); }, [onLoaded, invalidate]);

  const endIntro = () => {
    const st = s.current;
    if (st.phase !== 'intro') return;
    st.phase = 'follow';
    st.vPos.set(0, 0, 0); st.vTgt.set(0, 0, 0);
    live.current.onIntroDone();
  };
  // Skip: cut to the end of the intro (the pose for the current scroll position).
  useEffect(() => {
    if (!skip) return;
    const st = s.current;
    endIntro();
    st.placed = false;
    invalidate();
  }, [skip]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (reduced) { endIntro(); s.current.placed = false; } invalidate(); }, [reduced]); // eslint-disable-line react-hooks/exhaustive-deps

  // Ambience: the LightPulse clip (scale) + emissive breathing on the status ring, and the key sweep in useFrame.
  useEffect(() => {
    const p = player.current;
    if (!p) return;
    if (ambience && !reduced) p.play(); else p.pause();
    invalidate();
  }, [ambience, reduced, invalidate]);

  const goalFor = (p: number, aspect: number, out: { pos: Vector3; tgt: Vector3; fov: number }) => {
    const frame = aspect < 0.95 ? 'tall' : 'wide';
    const last = BEAT_POSES.length - 1;
    const x = p * last;
    let i = Math.min(last - 1, Math.floor(x)), f = x - i;
    if (live.current.reduced) { i = Math.round(x); f = 0; if (i > last - 1) { i = last - 1; f = 1; } }
    // hold each beat for the middle of its scroll range, travel in between
    const k = live.current.reduced ? f : smooth(MathUtils.clamp((f - 0.22) / 0.56, 0, 1));
    const a = BEAT_POSES[i][frame], b = BEAT_POSES[i + 1][frame];
    out.pos.set(...a.position).lerp(new Vector3(...b.position), k);
    out.tgt.set(...a.target).lerp(new Vector3(...b.target), k);
    out.fov = a.fov + (b.fov - a.fov) * k;
  };
  const goal = useMemo(() => ({ pos: new Vector3(), tgt: new Vector3(), fov: 30 }), []);

  useFrame((state, rawDt) => {
    const st = s.current;
    const dt = Math.min(rawDt, 1 / 20);
    const { reduced: still, ambience: amb } = live.current;
    const aspect = state.size.width / Math.max(1, state.size.height);
    goalFor(progress.current, aspect, goal);
    let busy = false;

    if (st.phase === 'intro') {
      if (progress.current > 0.015) endIntro();
      else {
        st.t = Math.min(1, st.t + dt / INTRO_SECONDS);
        const e = ease(st.t);
        // the path ends exactly on the first beat's pose
        const end = goal.pos;
        const p = e < 0.82 ? curve.getPoint(e / 0.82) : curve.getPoint(1).lerp(end, smooth((e - 0.82) / 0.18));
        st.pos.copy(p);
        st.tgt.set(...INTRO_TARGET_FROM).lerp(goal.tgt, smooth(Math.min(1, e * 1.15)));
        st.fov = 26 + (goal.fov - 26) * e;
        st.placed = true;
        busy = true;
        if (st.t >= 1) endIntro();
      }
    }
    if (st.phase === 'follow') {
      if (still || !st.placed) { st.pos.copy(goal.pos); st.tgt.copy(goal.tgt); st.fov = goal.fov; st.vPos.set(0, 0, 0); st.vTgt.set(0, 0, 0); st.placed = true; }
      else {
        damp3(st.pos, goal.pos, st.vPos, 0.65, dt);
        damp3(st.tgt, goal.tgt, st.vTgt, 0.65, dt);
        st.fov += (goal.fov - st.fov) * Math.min(1, dt * 4);
        busy = st.pos.distanceToSquared(goal.pos) > 1e-7 || st.tgt.distanceToSquared(goal.tgt) > 1e-7 || Math.abs(goal.fov - st.fov) > 1e-3;
      }
    }
    camera.position.copy(st.pos);
    camera.lookAt(st.tgt);
    if (Math.abs(camera.fov - st.fov) > 1e-4) { camera.fov = st.fov; camera.updateProjectionMatrix(); }

    // Lighting: intro fade-up, then a slow key sweep and the ring's breathing (only with ambience on).
    const key = lights.current?.key;
    const animated = amb && !still;
    if (animated) st.time += dt;
    const fade = st.phase === 'intro' ? smooth(Math.min(1, st.t * 2.2)) : 1;
    if (key) {
      const sweep = animated ? Math.sin(st.time * 0.23) * 0.55 : 0;
      const r = Math.hypot(KEY.position[0], KEY.position[2]), a0 = Math.atan2(KEY.position[2], KEY.position[0]);
      key.position.set(Math.cos(a0 + sweep) * r, KEY.position[1], Math.sin(a0 + sweep) * r);
      key.intensity = KEY.intensity * fade;
    }
    if (ring.current) ring.current.emissiveIntensity = animated ? 1.25 + 0.95 * (0.5 + 0.5 * Math.sin(st.time * 2.2)) : 1.7;
    if (busy && state.frameloop === 'demand') invalidate();
  });

  const onParts = useCallback((_: unknown, core: PartControllerCore) => {
    let mat: MeshStandardMaterial | null = null;
    core.root.getObjectByName('StatusLight')?.traverse((o) => { if ((o as Mesh).isMesh && !mat) mat = (o as Mesh).material as MeshStandardMaterial; });
    ring.current = mat;
    invalidate();
  }, [invalidate]);
  // The ring material is a PartController clone (the cached original is never touched); emissive starts at 1.7.
  const overrides = useMemo(() => ({ 'material:LightEmissive': { emissiveIntensity: 1.7 } }) as const, []);

  return (
    <>
      <LightingRig ref={lights} preset="product-contrast" shadowRadius={1.6} shadowOpacity={0.5} />
      {/* a flat matte stage disc: no rim to catch the strip lights behind the copy */}
      <mesh rotation-x={-Math.PI / 2} position-y={-0.001} receiveShadow>
        <circleGeometry args={[2.6, 72]} />
        <meshStandardMaterial color="#12110f" roughness={0.85} metalness={0} />
      </mesh>
      <ModelBoundary resetKey={variantUrl} onError={onError}>
        <Suspense fallback={null}>
          <ModelRig url={variantUrl} onModel={onModel} onParts={onParts} overrides={overrides} player={player} ambient={ambience && !reduced} onError={onError} />
        </Suspense>
      </ModelBoundary>
    </>
  );
}

/** The speaker, its material controller (clones the ring material) and the LightPulse clip. */
function ModelRig({ url, onModel, onParts, overrides, player, ambient, onError }: {
  url: string; onModel: (m: LoadedModel) => void; onError: (e: Error) => void; onParts: (p: unknown, c: PartControllerCore) => void;
  overrides: Readonly<Record<string, { emissiveIntensity: number }>>; player: MutableRefObject<AnimationPlayerHandle | null>; ambient: boolean;
}) {
  const [model, setModel] = useState<LoadedModel | null>(null);
  return (
    <>
      <Model src={url} scale={10} castShadow onLoaded={(m) => { setModel(m); onModel(m); }} onError={onError} />
      <PartController root={model?.scene ?? null} overrides={overrides} onReady={onParts} />
      <AnimationPlayer ref={player} root={model?.scene ?? null} clips={model?.animations ?? []} clip="LightPulse" loop autoPlay={ambient} />
    </>
  );
}

/* Pulse Night Edition — black stage, one warm key, editorial serif against a heavy grotesque. */
.root { background: var(--mk-bg, #0e0e0c); }

.scene { position: relative; height: 300svh; }
.sticky {
  position: sticky;
  top: 44px;
  height: calc(100svh - 44px);
  overflow: hidden;
  background: radial-gradient(50% 62% at 68% 56%, #2b2219 0%, #15130f 52%, #0e0e0c 100%);
}
.poster {
  position: absolute;
  right: 4%;
  top: 50%;
  width: min(52%, 640px);
  transform: translateY(-50%);
}

.beats { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
.chrome { position: sticky; top: 44px; height: 0; z-index: 3; }
.chromeRow {
  position: absolute;
  top: 14px;
  left: 16px;
  right: 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.chromeRow button, .nav button { pointer-events: auto; }
.pill {
  min-height: 36px;
  padding: 0 16px;
  border: 1px solid var(--mk-line-strong, #f3f0e8);
  border-radius: 999px;
  background: var(--mk-bg, #0e0e0c);
  color: var(--mk-ink, #f3f0e8);
  font: 500 13px/1 var(--mk-font-text, system-ui, sans-serif);
}
.pill:hover { background: var(--mk-ink, #f3f0e8); color: var(--mk-bg, #0e0e0c); }
.nav {
  position: absolute;
  top: calc(50svh - 100px);
  right: 16px;
  display: none;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}
.navItem {
  min-height: 32px;
  padding: 0 10px;
  border: 0;
  border-right: 2px solid var(--mk-line, #f3f0e826);
  background: none;
  color: var(--mk-ink-muted, #a8a59a);
  font-size: 13px;
}
.navItem[aria-current='step'] { color: var(--mk-ink, #f3f0e8); border-right-color: var(--mk-signal, #ff5a2b); }

.beat {
  display: flex;
  align-items: flex-end;
  height: 100svh;
  padding: 72px 16px 20px;
  scroll-margin-top: 44px;
}
.copy {
  display: grid;
  gap: 14px;
  width: 100%;
  max-width: 31rem;
  padding: 18px;
  border: 1px solid var(--mk-line, #f3f0e826);
  border-radius: var(--mk-radius-m, 10px);
  background: var(--mk-bg, #0e0e0c);
}
.headline :global(h2), .headline h2 { font-size: clamp(2.3rem, 8.5cqi, 5.6rem); max-width: 11ch; color: var(--mk-ink, #f3f0e8); }
.title {
  margin: 0;
  font-family: var(--mk-font-display, system-ui, sans-serif);
  font-weight: 700;
  font-size: clamp(2rem, 6cqi, 4rem);
  line-height: 0.98;
  letter-spacing: -0.035em;
}
.rule { display: inline-block; width: 48px; height: 1px; background: var(--mk-line-strong, #f3f0e8); }

@container (width >= 48rem) {
  .sticky { background: radial-gradient(42% 60% at 70% 54%, #2b2219 0%, #15130f 55%, #0e0e0c 100%); }
  .beat { align-items: center; padding: 96px 8% 48px; }
  .beatRight { justify-content: flex-end; padding-right: 12%; }
  .copy { padding: 0; border: 0; background: none; }
  .nav { display: flex; }
}
@container (width < 48rem) {
  .sticky { background: radial-gradient(70% 45% at 50% 34%, #2b2219 0%, #15130f 60%, #0e0e0c 100%); }
  .poster { left: 50%; right: auto; top: 30%; width: min(78%, 420px); transform: translate(-50%, -50%); }
}
